import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, mix, smoothstep, uniform, mx_noise_float, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, Color, SRGBColorSpace, RepeatWrapping } = ctx.THREE;

  const group = new Group();

  const timelines = [];
  const handlers = {};

  const specColors = config.intent?.visualSpec?.colors || config.colors || {};
  const ink = new Color(specColors.ink || '#16161d');
  const paper = new Color(specColors.paper || '#e8ecf2');
  const accent = new Color(specColors.accent || '#ff2a38');
  const surface = new Color(specColors.surface || '#0b0b10');

  const uInk = uniform(ink);
  const uSurface = uniform(surface);
  const uAccent = uniform(accent);

  const sourceRect = config.atlas?.sourceRect || { width: 512, height: 320 };
  const aspect = sourceRect.width / sourceRect.height;
  const cardHeight = 2.0;
  const cardWidth = cardHeight * aspect;

  const geometry = new PlaneGeometry(cardWidth, cardHeight);

  function buildColorNode(tex) {
    const u = uv();
    const v = u.y;

    const gradient = mix(uSurface, uInk, smoothstep(0.0, 1.0, v));

    let layer = gradient;
    if (tex) {
      layer = mix(gradient, texture(tex, u).xyz, 0.35);
    }

    const grain = mx_noise_float(u.mul(vec2(400.0, 250.0))).mul(0.06).add(1.0);
    const grained = layer.mul(grain);

    const topLine = smoothstep(0.92, 0.95, v);
    const accented = mix(grained, uAccent, topLine.mul(0.85));

    return vec4(accented, 1.0);
  }

  const material = new MeshBasicNodeMaterial({
    colorNode: buildColorNode(null),
    side: ctx.THREE.FrontSide,
    transparent: false,
    depthWrite: true,
    depthTest: true
  });

  const plane = new Mesh(geometry, material);
  plane.name = 'pricing-card-2-plane';
  group.add(plane);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      tex.wrapS = RepeatWrapping;
      tex.wrapT = RepeatWrapping;
      material.colorNode = buildColorNode(tex);
      material.needsUpdate = true;
      group.userData.loadedTexture = tex;
    }).catch(() => {
      // Texture failed; keep procedural gradient surface.
    });
  }

  group.userData.timelines = timelines;
  group.userData.handlers = handlers;

  group.userData.cleanup = () => {
    timelines.forEach((tl) => {
      if (tl && typeof tl.kill === 'function') {
        tl.kill();
      }
    });

    const loadedTexture = group.userData.loadedTexture;
    if (loadedTexture) {
      loadedTexture.dispose();
      group.userData.loadedTexture = null;
    }

    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return group;
}
